/* One-time compensation is part of the permanent, race+slot ledger. The fresh save
   is written with one atomic setItem, not a delete-before-credit sequence. */
resetRebuilt(id,n=1){
 this.check(id);this.slot(n);
 const current=this.read(id,n);
 if(!current?.reset)throw Error('此档不是待补偿的旧存档，操作已取消');
 const ledger=this.legacy(id,n);
 const prior=ledger.rebuildCompensation||null;
 const amount=prior?0:current.reset.tier;
 if(!prior){
  ledger.balance+=amount;
  ledger.total+=amount;
  ledger.rebuildCompensation={tier:amount,source:current.reset.source,claimedAt:new Date().toISOString()};
  this.putLegacy(id,n,ledger);
 }
 // A previously interrupted attempt retries without paying a second time.
 const next=new QGame(null,261014,id);
 const upgrades=ledger.upgrades||{};
 next.s.maxHp+=4*(upgrades.vigor||0);next.s.hp+=4*(upgrades.vigor||0);
 next.s.maxSpirit+=4*(upgrades.spirit||0);next.s.spirit+=4*(upgrades.spirit||0);
 next.s.attack+=upgrades.attack||0;
 const key=this.key(id,n);
 this.storage.setItem(key,JSON.stringify(next.state()));
 // At this point the new slot is readable even if cleanup is interrupted.
 try{this.storage.removeItem(this.backupKey(id,n));this.storage.removeItem(this.deathKey(id,n));}catch{}
 return {game:next,paid:amount,total:ledger.rebuildCompensation.tier};
}

